contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        // require non-empty list to exercise the loop (P requires this)
        require(_tos.length > 0);

        // perform the call and observe whether it reverts
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool _r) {
            reverted = false;
            ret = _r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General invariant: if the call did not revert then it must have returned true.
        // (This captures that the implementation either reverts on any internal failure or returns true.)
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

